Translate("ptBR", "krolg", {
	title = "Krolg",
	subtitle = "O Pelurso Não Corrompido",
	found = "Uma cabana solitária ao sul do Lago Mistral",
	hint = "Encontre o pelurso que vive sozinho ao sul do Lago Mistral.",
	allegiance = "Pelursos",
	sections = {
		{
			title = "Resumo",
			text = [=[Krolg é um {link:furbolgs}pelurso{/link} que escapou do Musgo Vil e de sua corrupção. Foi expulso de sua tribo e vive sozinho. Só fala com os de sua espécie. Krolg culpa os elfos noturnos pelo que aconteceu aos pelursos, e seu ódio arde. Ainda assim, ele é justo. Não queria ver crianças élficas sofrerem e sustenta que os pelursos devem responder por seu próprio mal. Por isso pediu que {link:ran-bloodtooth}Ran Bloodtooth{/link} fosse morto.]=],
		},
		{
			title = "Feitos",
			text = [=[• Revelou-se a alguém que veio na forma de um {link:furbolgs}pelurso{/link}.
• Pediu a morte de {link:ran-bloodtooth}Ran Bloodtooth{/link}.]=],
		},
	},
	mentions = {
		{ text = "A Purificação de {link:raene-wolfrunner}Raene{/link}" },
		{ text = "A Purificação de {link:raene-wolfrunner}Raene{/link}" },
	},
	bonds = {
		{ id = "ran-bloodtooth", name = "Ran Bloodtooth", note = "o mal que ele queria ver acabado" },
		{ id = "raene-wolfrunner", name = "Raene Wolfrunner", note = "uma aliada sem saber" },
	},
})

Translate("ptBR", "ran-bloodtooth", {
	title = "Ran Bloodtooth",
	subtitle = "Rei dos Bloodtooth",
	found = "Aldeia Dente Sangrento, no sul de Vale Gris",
	hint = [=[Cuidado com o senhor pelurso cujo acampamento fica perto da borda sul da floresta.]=],
	allegiance = "Pelursos",
	sections = {
		{
			title = "Resumo",
			text = [=[Ran Bloodtooth é o mais temido dos pelursos corrompidos de {link:ashenvale}Vale Gris{/link}. Já tinha sede de poder antes que a corrupção o tocasse, e a corrupção só o tornou mais forte. Sua mente já não lhe pertence. Seu ódio arde ainda mais que o de {link:krolg}Krolg{/link}, e ele é uma ameaça a toda criatura da floresta. As {link:sentinels}Sentinelas{/link} o apontaram como a ameaça {link:furbolgs}pelurso{/link} mais feroz de Vale Gris. Seu crânio agora repousa num lugar de honra em {link:astranaar}Astranaar{/link}.]=],
		},
	},
	mentions = {
		{ text = "A Purificação de {link:raene-wolfrunner}Raene{/link}" },
		{ text = "A Purificação de {link:raene-wolfrunner}Raene{/link}" },
	},
	bonds = {
		{ id = "krolg", name = "Krolg", note = "queria vê-lo morto" },
		{ id = "raene-wolfrunner", name = "Raene Wolfrunner", note = "guarda seu crânio" },
	},
})

Translate("ptBR", "dal-bloodclaw", {
	title = "Dal Bloodclaw",
	subtitle = "Chefe dos Pelocardo",
	found = "Aldeia dos Pelocardo, ao norte de Astranaar",
	hint = "Procure o chefe dos pelursos ao norte de Astranaar.",
	allegiance = "Pelursos · Pelocardo",
	sections = {
		{
			title = "Resumo",
			text = [=[Dal Bloodclaw é o chefe dos pelursos {link:thistlefur-village}Pelocardo{/link}. Sob ele a tribo cresceu muito em número, e as batedoras de {link:astranaar}Astranaar{/link} temem que em breve ela esteja ousada o bastante para atacar a cidade. {link:raene-wolfrunner}Raene Wolfrunner{/link} pediu o crânio dele, como prova de que os Pelocardo tinham sido contidos. Ela não fingiu que isso acabaria com a ameaça. Ganharia tempo, e tempo era tudo o que ela podia esperar.]=],
