		{ id = "raene-wolfrunner", name = "Raene Wolfrunner", note = "queria seu crânio" },
	},
})

Translate("ptBR", "shindrell-swiftfire", {
	title = "Shindrell Swiftfire",
	subtitle = "Sentinela de Astranaar",
	found = "Astranaar",
	hint = [=[Fale com a sentinela que vigia as costas a partir de Astranaar.]=],
	allegiance = "Sentinelas",
	aliases = { "Shindrell" },
	sections = {
		{
			title = "Resumo",
