			title = "Resumo",
			text = [=[Pelturas Whitemoon é um {link:night-elves}elfo noturno{/link} de {link:astranaar}Astranaar{/link} cuja filha, Relara, adoeceu gravemente. Seu mal era mais que uma doença do corpo. Ela era atormentada por pesadelos, ardia em febre e enfraquecia a cada hora. O druida {link:orendil-broadleaf}Orendil Broadleaf{/link} lhe enviou uma cura e lhe falou de outros remédios caso ela falhasse. Pelturas seguiu cada um deles.]=],
		},
	},
	chapters = {
		{
			title = "A Cura de Relara",
			hint = [=[Reúna os remédios de Orendil para a criança doente de Astranaar.]=],
			text = [=[A primeira cura apenas retardou a doença. A Lágrima de Eluna, da ilha do {link:iris-lake}Lago Íris{/link}, lavou os pesadelos. A poeira gelada das {link:the-ruins-of-stardust}Ruínas de Poeira Estelar{/link} quebrou a febre. Por último, uma pedra-da-lua caída, arrancada do tesouro do oráculo Shadethicket, devolveu a Relara suas forças. Pelturas deu seu bem mais precioso em agradecimento.]=],
		},
	},
	mentions = {
		{ text = "A Cura de {link:orendil-broadleaf}Orendil{/link}" },
		{ text = "A Lágrima de Eluna" },
		{
			text = [=[As {link:the-ruins-of-stardust}Ruínas de Poeira Estelar{/link}]=],
		},
	},
	bonds = {
		{ id = "orendil-broadleaf", name = "Orendil Broadleaf", note = "enviou as curas" },
	},
})

