Translate("ptBR", "je-neu-sancrea", {
	title = "Je'neu Sancrea",
	subtitle = "Xamã do Anel da Terra",
	found = "Assentamento Zoram'gar, junto ao mar",
	hint = [=[Fale com o troll do Anel da Terra que vigia as ondas em Zoram'gar.]=],
	allegiance = "Anel da Terra · Horda",
	aliases = { "Je'neu" },
	sections = {
		{
			title = "Resumo",
			text = [=[Je'neu Sancrea é um xamã troll do {link:earthen-ring}Anel da Terra{/link} que vive no {link:zoram-gar-outpost}Assentamento Zoram'gar{/link}. Ele estuda a água e todos os elementos com tanta atenção que muitas vezes nem nota as pessoas ao seu redor. Veio à {link:the-zoram-strand}Praia de Zoram{/link} a mando do Anel da Terra, pois algo sob o mar está voltando os elementos contra o mundo.]=],
		},
		{
			title = "Importância",
			text = [=[Je'neu é o vigia da {link:horde}Horda{/link} sobre as {link:blackfathom-deeps}Profundezas Negras{/link}. Por meio dele, o Anel da Terra soube que o {link:twilight-s-hammer}Martelo do Crepúsculo{/link} chegara ao templo submerso e pretendia despertar poderes que os xamãs esperavam ter desaparecido para sempre.]=],
		},
		{
			title = "Feitos",
			text = [=[• Estudou o globo conspurcado do {link:mystral-lake}Lago Mistral{/link}.
• Descobriu o nome de {link:lorgus-jett}Lorgus Jett{/link} e pediu sua morte.
• Buscou um núcleo abissal que registra toda atividade elemental nas ruínas.
• Estudou o globo que alimentava o elemental corrompido {link:baron-aquanis}Barão Aquanis{/link}.]=],
		},
	},
	chapters = {
		{
			title = "As Safiras de Aku'Mai",
			hint = [=[Descubra por que os nagas colhem cristais nos túneis das Profundezas Negras.]=],
			text = [=[Nos primeiros túneis das {link:blackfathom-deeps}Profundezas Negras{/link}, grandes aglomerados de safira crescem nas paredes, e os espíritos da água se agarram a eles. Os nagas tinham começado a colhê-los. Je'neu não sabia por quê, mas temia que os cristais pudessem virar uma arma poderosa nas mãos erradas. Mandou tomá-los antes que os nagas pudessem usá-los.]=],
		},
		{
			title = "Lealdade aos Deuses Antigos",
			hint = "Siga o bilhete úmido encontrado nas profundezas.",
			text = [=[Um bilhete amassado contou o resto. As sacerdotisas dos nagas deveriam levar os cristais a um homem chamado {link:lorgus-jett}Lorgus Jett{/link}, que pretendia usar seu poder para agradar a um ser chamado {link:aku-mai}Aku'Mai{/link} e chamá-lo de volta ao mundo. Ele sonhava com uma nova era governada pelos {red:old-gods}Deuses Antigos{/red}. Lorgus era do {link:twilight-s-hammer}Martelo do Crepúsculo{/link}. Je'neu estava fraco demais para enfrentá-lo e enviou outros às profundezas para acabar com ele.]=],
		},
		{
			title = "O Núcleo Abissal",
			hint = "Busque a pedra que se lembra dos elementos.",
			text = [=[O {link:twilight-s-hammer}Martelo do Crepúsculo{/link} tomara as Moonshrine Ruins dentro das profundezas. Je'neu pediu o núcleo abissal que ficava na pedra abissal das ruínas, um dispositivo que guarda o registro de cada movimento dos elementos. Com ele, e com o estranho globo que alimentara o corrompido {link:baron-aquanis}Barão Aquanis{/link}, o Anel da Terra poderia começar a descobrir o que o culto estava fazendo, e como.]=],
		},
	},
	mentions = {
		{ text = "Je'neu do Anel da Terra" },
		{ text = "Problemas nas {link:blackfathom-deeps}Profundezas{/link}" },
	},
	bonds = {
		{ id = "mastok-wrilehiss", name = "Mastok Wrilehiss", note = "enviou-lhe o globo" },
		{ id = "tideress", name = "Tideress", note = "o espírito conspurcado que ele estudou" },
		{ id = "karang-amakkar", name = "Karang Amakkar", note = "comanda seu posto" },
	},
})

